use super::*;
use crate::model_pool::{Policy,State};
use std::sync::{Arc,Mutex};
#[derive(Clone,Debug)]
pub enum Command{Adapt{run:RunId},Restrict{run:RunId,allowed:Vec<Mode>,approved:String},Init{run:RunId,policy:Policy},Inspect{run:RunId,result:Arc<Mutex<Option<State>>>},Phase{run:RunId,approved:String,handoff:Vec<String>},Advance{run:RunId},Reconcile{run:RunId,request:RequestId,approved:String,evidence:String},Activation{run:RunId,approved:String,old_unloaded:bool,new_resident:bool,evidence:String}}
pub(super) fn get(db:&Connection,run:RunId)->Result<Option<State>>{let mut q=db.prepare("SELECT revision,document FROM model_pools WHERE run_id=?1")?;let mut rows=q.query([run.0.to_string()])?;let Some(row)=rows.next()?else{return Ok(None);};let revision:i64=row.get(0)?;let text:String=row.get(1)?;if text.len()>128*1024{return Err(Error::Unsupported);}let state:State=serde_json::from_str(&text).map_err(|_|Error::State)?;if sql_integer(state.revision)?!=revision{return Err(Error::State);}Ok(Some(state))}
fn save(tx:&Transaction<'_>,run:RunId,state:&mut State)->Result<()>{let expected=state.revision;state.revision=state.revision.checked_add(1).ok_or(Error::State)?;let text=serde_json::to_string(state).map_err(|_|Error::State)?;if text.len()>128*1024{return Err(Error::Unsupported);}let n=tx.execute("UPDATE model_pools SET revision=?1,document=?2 WHERE run_id=?3 AND revision=?4",params![sql_integer(state.revision)?,text,run.0.to_string(),sql_integer(expected)?])?;if n!=1{return Err(Error::Conflict);}Ok(())}
pub(super) fn fence_all(tx:&Transaction<'_>,epoch:u64)->Result<()>{let mut ids=vec![];{let mut q=tx.prepare("SELECT run_id FROM model_pools LIMIT 1025")?;for id in q.query_map([],|r|r.get::<_,String>(0))?{if ids.len()>=1024{return Err(Error::Unsupported);}ids.push(id?);}}for id in ids{let run=RunId(uuid::Uuid::parse_str(&id).map_err(|_|Error::State)?);let mut state=get(tx,run)?.ok_or(Error::State)?;state.fence(epoch);save(tx,run,&mut state)?;}Ok(())}
pub(super) fn reserve(tx:&Transaction<'_>,run:RunId,request:RequestId,claim:&crate::scheduler::Claim,profile:Option<String>,context:u64)->Result<()>{if let Some(mut state)=get(tx,run)?{let profile=profile.ok_or(Error::Denied)?;if state.epoch!=claim.epoch{return Err(Error::Denied);}let graph=coordination::graph(tx,run)?;let actor=graph.plan.agents.iter().position(|a|a.id==claim.actor).ok_or(Error::Denied)?;let task=graph.nodes.iter().position(|n|n.task.id==claim.task).ok_or(Error::Denied)?;state.reserve(request,claim.actor,actor,task,&profile,context)?;save(tx,run,&mut state)?;}else if profile.is_some(){return Err(Error::Denied);}Ok(())}
pub(super) fn settle(tx:&Transaction<'_>,run:RunId,request:RequestId,known:bool)->Result<()>{if let Some(mut state)=get(tx,run)?{state.settle(request,known)?;save(tx,run,&mut state)?;}Ok(())}
pub(super) fn apply(tx:&Transaction<'_>,command:Command,revision:u64,epoch:u64)->Result<()>{
    let run=match &command{Command::Adapt{run}|Command::Restrict{run,..}|Command::Init{run,..}|Command::Inspect{run,..}|Command::Phase{run,..}|Command::Advance{run}|Command::Reconcile{run,..}|Command::Activation{run,..}=>*run};if let Command::Inspect{result,..}=command{*result.lock().map_err(|_|Error::State)?=get(tx,run)?;return Ok(());}
    if let Command::Init{policy,..}=command{if revision!=0{return Err(Error::Conflict);}let graph=coordination::graph(tx,run)?;if policy.adaptive.as_ref().is_some_and(|p|p.initial!=graph.plan.mode){return Err(Error::Invalid);}let mut others=tx.prepare("SELECT document FROM model_pools WHERE run_id!=?1 LIMIT 1025")?;for row in others.query_map([run.0.to_string()],|r|r.get::<_,String>(0))?{let other:State=serde_json::from_str(&row?).map_err(|_|Error::State)?;for held in &other.reservations{let p=other.policy.profile(&held.profile)?;if policy.profiles.iter().any(|v|v.instance==p.instance||v.provider.endpoint==p.provider.endpoint&&v.provider.model==p.provider.model){return Err(Error::Recovery);}}if other.activation.is_some(){return Err(Error::Recovery);}}let state=State::new(policy,epoch,graph.plan.agents.len(),graph.nodes.len())?;tx.execute("INSERT INTO model_pools VALUES(?1,0,?2)",params![run.0.to_string(),serde_json::to_string(&state).map_err(|_|Error::State)?])?;audit(tx,&run.0.to_string(),"user","model-policy-admitted")?;return Ok(());}
    let mut state=get(tx,run)?.ok_or(Error::Unsupported)?;if state.revision!=revision||state.epoch!=epoch{return Err(Error::Conflict);}
    let kind=match command{
        Command::Restrict{allowed,approved,..}=>{if crate::model_pool::digest(&crate::model_pool::review_state(&state))?!=approved{return Err(Error::Denied);}let adaptive=state.policy.adaptive.as_mut().ok_or(Error::Unsupported)?;if allowed.iter().any(|m|!adaptive.allowed.contains(m)){return Err(Error::Denied);}adaptive.allowed=allowed;"adaptive-allowlist-restricted"},
        Command::Adapt{..}=>{
            if state.policy.adaptive.is_none(){return Ok(());}let old=coordination::graph(tx,run)?;if old.nodes.iter().any(|n|n.lease.is_some())||!state.reservations.is_empty()||state.activation.is_some()||crate::lifecycle::uncertain(tx,run)?{return Err(Error::Denied);}
            if !old.nodes.iter().any(|n|n.task.kind==crate::scheduler::Kind::Coordinate&&n.state==crate::scheduler::Status::WaitingChildren){return Ok(());}let pending:bool=tx.query_row("SELECT EXISTS(SELECT 1 FROM messages WHERE run_id=?1 AND ack_digest IS NULL)",[run.0.to_string()],|r|r.get(0))?;if pending{return Ok(());}
            let current=crate::lifecycle::snapshot(tx,run)?;if current.state!="active"{return Err(Error::Denied);}let(tokens,cost):(i64,i64)=tx.query_row("SELECT token_limit-token_charged-token_reserved,cost_limit-cost_charged-cost_reserved FROM run_budgets WHERE run_id=?1",[run.0.to_string()],|r|Ok((r.get(0)?,r.get(1)?)))?;
            let Some((mut next,assignments))=crate::adaptive::choose(&old,&state,tokens.try_into().map_err(|_|Error::State)?,(current.spec.step_budget-current.steps) as u64,cost.try_into().map_err(|_|Error::State)?)?else{return Ok(());};
            let previous=serde_json::to_string(&old).map_err(|_|Error::State)?;state.adaptations+=1;tx.execute("INSERT INTO mode_history VALUES(?1,?2,?3,?4)",params![run.0.to_string(),state.adaptations,previous,crate::model_pool::digest(&state.policy.adaptive)?])?;
            for agent in &next.plan.agents{let role=serde_json::to_value(&agent.role).map_err(|_|Error::State)?;tx.execute("INSERT INTO agents VALUES(?1,?2,?3) ON CONFLICT DO NOTHING",params![agent.id.0.to_string(),run.0.to_string(),role.as_str()])?;}
            next.revision=old.revision+1;tx.execute("UPDATE coordination SET revision=?1,document=?2 WHERE run_id=?3 AND revision=?4",params![sql_integer(next.revision)?,serde_json::to_string(&next).map_err(|_|Error::State)?,run.0.to_string(),sql_integer(old.revision)?])?;
            for node in &next.nodes{tx.execute("UPDATE tasks SET owner_agent_id=?1,revision=?2 WHERE id=?3 AND run_id=?4",params![node.task.actor.0.to_string(),sql_integer(node.revision)?,node.task.id.0.to_string(),run.0.to_string()])?;}
            let mut spec=current.spec;spec.mode=next.plan.mode.clone();spec.roles=next.plan.agents.iter().map(|a|a.role.clone()).collect();spec.permission_epoch=spec.permission_epoch.checked_add(1).ok_or(Error::State)?;spec.validate()?;crate::lifecycle::spec_record(tx,&spec,current.version+1)?;tx.execute("UPDATE run_lifecycle SET revision=revision+1 WHERE run_id=?1",[run.0.to_string()])?;tx.execute("UPDATE runs SET mode=?1,revision=revision+1 WHERE id=?2",params![serde_json::to_value(&spec.mode).map_err(|_|Error::State)?.as_str(),run.0.to_string()])?;tx.execute("DELETE FROM grants WHERE operation_id IN(SELECT id FROM operations WHERE run_id=?1)",[run.0.to_string()])?;tx.execute("DELETE FROM forwarding_consents WHERE run_id=?1",[run.0.to_string()])?;state.policy.assignments=assignments;"adaptive-composition-changed"
        },
        Command::Phase{approved,handoff,..}=>{state.approve_phase(&approved,handoff)?;"relay-phase-approved"},
        Command::Advance{..}=>{if !state.reservations.is_empty()||state.activation.is_some()||!state.phase_approved{return Err(Error::Denied);}let graph=coordination::graph(tx,run)?;let phase=state.policy.phases.get(state.phase).ok_or(Error::Invalid)?;let done=phase.tasks.iter().all(|i|graph.nodes.get(*i).is_some_and(|n|match phase.goal{crate::model_pool::PhaseGoal::Succeeded=>n.state==crate::scheduler::Status::Succeeded,crate::model_pool::PhaseGoal::WaitingOrSucceeded=>matches!(n.state,crate::scheduler::Status::WaitingChildren|crate::scheduler::Status::Succeeded)}));if !done{return Err(Error::Denied);}state.phase+=1;state.phase_approved=false;"relay-phase-drained"},
        Command::Reconcile{request,approved,evidence,..}=>{if crate::model_pool::digest(&state)?!=approved||evidence.len()!=64||!state.reservations.iter().any(|r|r.request==request&&r.unknown){return Err(Error::Denied);}state.settle(request,true)?;"owner-observed-provider-request-complete-no-budget-refund"},
        Command::Activation{approved,old_unloaded,new_resident,evidence,..}=>{state.observe_activation(&approved,old_unloaded,new_resident,&evidence)?;"owner-observed-model-activation"},Command::Inspect{..}|Command::Init{..}=>unreachable!()
    };save(tx,run,&mut state)?;audit(tx,&run.0.to_string(),"user",kind)
}
impl Ledger{
    pub async fn model_state(&self,run:RunId)->Result<Option<State>>{let result=Arc::new(Mutex::new(None));self.transition(0,Transition::ModelPool{command:Command::Inspect{run,result:result.clone()}}).await?;result.lock().map_err(|_|Error::State)?.take().map(Some).ok_or(Error::Unsupported).or_else(|e|if matches!(e,Error::Unsupported){Ok(None)}else{Err(e)})}
    pub async fn model_command(&self,revision:u64,command:Command)->Result<()>{self.transition(revision,Transition::ModelPool{command}).await}
}
